ИНДЕКСИРОВАТЬ ПО ВТ_ВсеСчетчики.Объект ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ ЕСТЬNULL(ВТ_ИтоговаяТаблица.Объект, "") КАК ОбъектУстановки, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик, "") КАК Счетчик, ЕСТЬNULL(ВТ_ИтоговаяТаблица.Счетчик.Код, "") КАК СсылочныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ПочтовыйАдрес, "") КАК АдресДома, ЕСТЬNULL(бит_Счетчики.ЗаводскойСерийныйНомерПУ, "") КАК ЗаводскойСерийныйНомерПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидПУ, "") КАК ВидПУ, ЕСТЬNULL(бит_Счетчики.МаркаПУ, "") КАК МаркаПУ, ЕСТЬNULL(ВТ_ИтоговаяТаблица.ВидКоммунальногоРесурса, "") КАК ВидКоммунальногоРесурса, ЕСТЬNULL(КлассификаторЕдиницИзмерения.НаименованиеПолное, "") КАК ЕдиницаИзмерения, ЕСТЬNULL(ВТ_ИтоговаяТаблица.БазовоеПоказание, 0) КАК БазовоеПоказание ИЗ ВТ_ИтоговаяТаблица КАК ВТ_ИтоговаяТаблица ЛЕВОЕ СОЕДИНЕНИЕ Справочник.бит_Счетчики КАК бит_Счетчики ПО ВТ_ИтоговаяТаблица.Счетчик = бит_Счетчики.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Справочник.КлассификаторЕдиницИзмерения КАК КлассификаторЕдиницИзмерения ПО ВТ_ИтоговаяТаблица.ЕдИзм = КлассификаторЕдиницИзмерения.Ссылка
